mapper.select:
select tu.*, tu2.id createById, tu2.name createByName, tu3.id editById, tu3.name editByName
from t_user tu left join t_user tu2 on tu.create_by = tu2.id left join t_user tu3 on tu.edit_by = tu3.id
where tu.id = #{id, jdbcType=INTEGER}

WITH RECURSIVE organization_ancestry(descendant_id,ancestor_id,parent_id) AS ( SELECT id,id,parent_id FROM t_organization_unit UNION ALL SELECT ancestry.descendant_id,parent.id,parent.parent_id FROM organization_ancestry ancestry INNER JOIN t_organization_unit parent ON parent.id=ancestry.parent_id ) select distinct tu.id, tu.name from t_user tu inner join t_user_role tur on tu.id = tur.user_id and tur.active_marker=1 and (tur.effective_from is null or tur.effective_from <= CURRENT_TIMESTAMP) and (tur.effective_to is null or tur.effective_to > CURRENT_TIMESTAMP) inner join t_role tr on tur.role_id = tr.id and tr.enabled = 1 inner join t_employee employee on employee.user_id = tu.id and employee.employment_status = 'ACTIVE' inner join t_employee_assignment assignment on assignment.employee_id = employee.id and assignment.assignment_type = 'PRIMARY' and assignment.status = 'ACTIVE' and assignment.active_primary_marker = 1 and assignment.effective_from <= CURRENT_TIMESTAMP and (assignment.effective_to is null or assignment.effective_to > CURRENT_TIMESTAMP) inner join t_organization_unit organization on organization.id=assignment.organization_unit_id and organization.enabled=1 and organization.migration_placeholder=0 inner join t_position position on position.id = assignment.position_id and position.enabled = 1 and position.code <> 'UNASSIGNED_POSITION' where tu.account_enabled = 1 and tu.account_no_locked = 1 and tu.account_type='HUMAN' and tu.protected_account=0 and ( exists (select 1 from t_role_permission owner_rp inner join t_permission owner_permission on owner_permission.id=owner_rp.permission_id and owner_permission.enabled=1 and owner_permission.code=#{permissionCode} where owner_rp.role_id=tr.id) or exists (select 1 from t_user_permission owner_up inner join t_permission owner_permission on owner_permission.id=owner_up.permission_id and owner_permission.enabled=1 and owner_permission.code=#{permissionCode} where owner_up.user_id=tu.id and owner_up.effect='GRANT' and owner_up.active_marker=1 and owner_up.effective_from <= CURRENT_TIMESTAMP and (owner_up.effective_to is null or owner_up.effective_to > CURRENT_TIMESTAMP)) ) and not exists (select 1 from t_user_permission owner_deny inner join t_permission denied_permission on denied_permission.id=owner_deny.permission_id and denied_permission.code=#{permissionCode} where owner_deny.user_id=tu.id and owner_deny.effect='DENY' and owner_deny.active_marker=1 and owner_deny.effective_from <= CURRENT_TIMESTAMP and (owner_deny.effective_to is null or owner_deny.effective_to > CURRENT_TIMESTAMP)) and (tr.scope_type='GLOBAL' or exists ( select 1 from t_role_organization applicable inner join organization_ancestry ancestry on ancestry.descendant_id=assignment.organization_unit_id and ancestry.ancestor_id=applicable.organization_unit_id where applicable.role_id=tr.id ))
and tu.id in #{visibleUserId}
order by tu.name, tu.id

select id from t_activity
where owner_id = #{userId, jdbcType=INTEGER}
order by id asc

select id from t_clue
where owner_id = #{userId, jdbcType=INTEGER}
order by id asc

mapper.update:
update t_user set authorization_version = authorization_version + 1,
  auth_version = auth_version + 1, edit_time = CURRENT_TIMESTAMP
where id = #{id} and authorization_version = #{expectedVersion}

UPDATE t_user SET login_act=#{loginAct},auth_version=auth_version+1,version=version+1,
  edit_by=#{operatorId},edit_time=CURRENT_TIMESTAMP
WHERE id=#{id} AND version=#{expectedVersion}

update t_user
login_act = #{loginAct}, login_pwd = #{loginPwd}, `name` = #{name}, phone = #{phone}, email = #{email}, account_no_expired = #{accountNoExpired}, credentials_no_expired = #{credentialsNoExpired}, account_no_locked = #{accountNoLocked}, account_enabled = #{accountEnabled}, create_time = #{createTime}, create_by = #{createBy}, edit_time = #{editTime}, edit_by = #{editBy}, last_login_time = #{lastLoginTime},
where id = #{id}

update t_user set login_act = #{loginAct}, login_pwd = #{loginPwd}, `name` = #{name}, phone = #{phone},
email = #{email}, account_no_expired = #{accountNoExpired}, credentials_no_expired = #{credentialsNoExpired},
account_no_locked = #{accountNoLocked}, account_enabled = #{accountEnabled}, create_time = #{createTime},
create_by = #{createBy}, edit_time = #{editTime}, edit_by = #{editBy}, last_login_time = #{lastLoginTime}
where id = #{id}
